function Picker({value,onChange,options,label:idLabel}:{value:string;onChange:(v:string)=>void;options:string[][];label:string}){return <Select dir="rtl" value={value} onValueChange={onChange}><SelectTrigger aria-label={idLabel}><SelectValue/></SelectTrigger><SelectContent>{options.map(([v,t])=><SelectItem key={v} value={v}>{t}</SelectItem>)}</SelectContent></Select>}
function TextField({label:caption,value,onChange,type='text',help}:{label:string;value:string;onChange:(s:string)=>void;type?:string;help?:string}){return <label className="field"><span>{caption}</span><Input type={type} value={value} onChange={e=>onChange(e.target.value)}/>{help&&<span className="field-help">{help}</span>}</label>}
function NumField({label:caption,value,onChange,help}:{label:string;value:number|null;onChange:(v:number|null)=>void;help?:string}){return <label className="field"><span>{caption}</span><Input type="number" step="any" value={value??''} onChange={e=>onChange(e.target.value===''?null:parseNumber(e.target.value))}/>{help&&<span className="field-help">{help}</span>}</label>}
function CheckLine({checked,onChange,children}:{checked:boolean;onChange:(v:boolean)=>void;children:React.ReactNode}){return <label className="check-row"><Checkbox checked={checked} onCheckedChange={v=>onChange(v===true)}/><span>{children}</span></label>}
