 const score=scoreFor(mode);const advice={strength:base.factors.filter(f=>f.score!==null&&f.score<=35).map(f=>f.name+': '+f.reason),weakness:base.factors.filter(f=>f.score!==null&&f.score>=60).map(f=>f.name+': '+f.reason)};const problemList=[...base.blockers,...(extra.gated?['تحقق من الفحص الشرعي وآخر ربع، واتساق عملة المركز والمستويات وحداثة العرض والطلب.']:[]),...missing.map(v=>'استكمل: '+v)];
 const setM=(k:keyof Meta,v:string)=>{setMeta(p=>({...p,[k]:v}));setChecks(blankChecks());setReq(p=>({...p,historyReviewed:false,planReviewed:false}))};
