    let pp:Price[]=[];if(Array.isArray(data.prices)&&data.prices.length){pp=parsePrices('date,open,high,low,close,volume\n'+data.prices.map((x:any)=>[x.date,x.open,x.high,x.low,x.close,x.volume].join(',')).join('\n'))}
    if(demo||data.appFormat==='mizan-v1')reset();setFinancials(f);const metaNew=blankMeta();for(const k of Object.keys(metaNew) as (keyof Meta)[]){if(typeof data.meta?.[k]==='string')metaNew[k]=data.meta[k].slice(0,3000)}if(data.meta){setMeta(metaNew)}else setMeta(p=>({...p,financialSource:file.name}));
    if(pp.length)setPrices(pp);if(data.appFormat==='mizan-v1'){
     const re=blankRequirements();for(const k of Object.keys(re) as (keyof Requirements)[]){const value=data.requirements?.[k];if(typeof re[k]==='boolean')continue;if(re[k]===null||typeof re[k]==='number'){(re as any)[k]=parseNumber(value)}else if(typeof value==='string')(re as any)[k]=value.slice(0,6000)}setReq(re);
     if(Array.isArray(data.history)&&data.history.length===3)setHistory(data.history.map((row:any)=>{const y=blankHistory()[0];for(const k of Object.keys(y) as (keyof YearRow)[]){if(typeof y[k]==='string'){(y as any)[k]=typeof row[k]==='string'?row[k].slice(0,3000):''}else (y as any)[k]=parseNumber(row[k])}return y}));
     const ev=blankEvents();for(const k of Object.keys(ev) as (keyof Events)[])ev[k]=data.events?.[k]===true;setEvents(ev);
    }
    setChecks(blankChecks());setDemo(data.demo===true);setSourceMap(Object.fromEntries(FIELDS.filter(x=>f[x.key]!==null).map(x=>[x.key,`${file.name} · ${x.key}`])));if(data.appFormat==='mizan-v1'&&data.sources&&typeof data.sources==='object'){setSourceMap(Object.fromEntries(FIELDS.filter(x=>typeof data.sources[x.key]==='string').map(x=>[x.key,data.sources[x.key].slice(0,12000)])))}setFiles([{name:file.name,kind:'مالي',count:n},...(pp.length?[{name:file.name,kind:'أسعار يومية',count:pp.length}]:[])]);setEdit(true);setStatus('تمت استعادة البيانات؛ يلزم إعادة مراجعة التواريخ والمصادر والاعتمادات.');
